public static void check(Solution solution) {
    assert Arrays.equals(solution.isArraySpecial(new int[]{2,2,2,2,2}, new int[]{{0,4}}), new int[]{False});
    assert Arrays.equals(solution.isArraySpecial(new int[]{2,4,6,8,10}, new int[]{{0,0},{1,1},{2,2},{3,3},{4,4},{0,4}}), new int[]{True, True, True, True, True, False});
    assert Arrays.equals(solution.isArraySpecial(new int[]{1,3,5,7,9}, new int[]{{0,1},{1,2},{2,3},{3,4}}), new int[]{False, False, False, False});
    assert Arrays.equals(solution.isArraySpecial(new int[]{1,3,5,7,9}, new int[]{{0,0},{1,1},{2,2},{3,3},{4,4},{0,4}}), new int[]{True, True, True, True, True, False});
    assert Arrays.equals(solution.isArraySpecial(new int[]{1,2,3,4,5}, new int[]{{0,1},{1,2},{2,3},{3,4}}), new int[]{True, True, True, True});
    assert Arrays.equals(solution.isArraySpecial(new int[]{1,2,3,4,5}, new int[]{{0,0},{1,2},{2,4}}), new int[]{True, True, True});
    assert Arrays.equals(solution.isArraySpecial(new int[]{3,4,1,2,6}, new int[]{{0,4}}), new int[]{False});
    assert Arrays.equals(solution.isArraySpecial(new int[]{1,3,5,7,9}, new int[]{{0,4}}), new int[]{False});
